select wi.review_time inboundTime, wi.review_time reviewTime, wi.create_time createTime, wi.user_update_time userUpdateTime, wi.id wid, wi.serial_number, wi.shipment_number shipmentNumber, wi.license_plate licensePlate, wi.supplier_id supplierId, wi.inbound_way, wi.inbound_way as inbound_way_detail, ss.name supplierName, spo.id purchaseId, spo.serial_number purchaseSN, wi.applicant_name applicantName, wi.editor_name editorName, wi.reviewer_name reviewerName, wid.*, ww.id warehouseId, ww.name warehouseName, mf.id workshopId, mf.name workshopName from wms_inbound_detail wid left join wms_inbound wi on wid.inbound_id = wi.id left join wms_warehouse ww on wid.warehouse_id = ww.id left join wms_workshop mf on mf.id = wid.workshop_id left join scm_supplier ss on ss.id = wi.supplier_id left join scm_purchase_order spo on spo.id = wi.purchase_id where wid.bool_delete_enum = 0 and wi.review_status = 2
and wid.basic_class & #{ basicClass} > 0
and wi.inbound_way = #{inboundWay}
and wi.bool_party_a = 1
and wi.bool_party_a = 0
and wid.reject_status = #{rejectStatus}
and wi.supplier_id = #{supplierId}
and wid.workshop_id = #{workshopId}
and wid.warehouse_id = #{warehouseId}
and wi.purchase_SN like CONCAT('%', #{purchaseSN},'%')
and wi.serial_number like CONCAT('%', #{inboundSN},'%')
and wi.license_plate like CONCAT('%', #{licensePlate},'%')
and wi.shipment_number like CONCAT('%', #{shipmentNumber},'%')
and (wi.editor_name like CONCAT('%', #{operatorName},'%') or wi.applicant_name like CONCAT('%', #{operatorName},'%') or wi.reviewer_name like CONCAT('%', #{operatorName},'%'))
and wid.project_id is null
and wid.project_id IS NOT NULL
AND wid.project_id = #{projectId}
and wid.classify_id in
#{item}
and wi.review_time > #{inboundTime[0]}
and wi.review_time < #{inboundTime[1]}
and wid.real_time > #{realTime[0]}
and wid.real_time < #{realTime[1]}
and wid.specification like CONCAT('%', #{specification},'%')
and wid.heat_no_and_batch_no like CONCAT('%', #{heatNoAndBatchNo},'%')
AND wid.brand like CONCAT('%', #{brand},'%')
and wid.theory_thickness = #{theoryThickness}
and wid.thickness = #{thickness}
and wid.width = #{width}
and wid.length = #{length}
-- 长度范围只用于钢卷查询,钢卷quantity计量量记录长度
and wid.quantity >= #{minLength}
and wid.quantity <= #{maxLength}
and wid.color like CONCAT('%', #{color},'%')
and wid.quality_testing_enum in
#{qualityTestingEnum}
and wid.workshop_id in
#{item}

SELECT wid.*, wi.purchase_SN purchase_sn, wi.serial_number AS inbound_serial_number, wi.applicant_id, wi.applicant_name, wi.reviewer_id, wi.reviewer_name FROM wms_inbound_detail AS wid INNER JOIN wms_inbound AS wi ON wi.id = wid.inbound_id AND wi.bool_delete_enum = 0 AND wi.review_status = 2 AND wi.reject_status != 8 INNER JOIN scm_purchase_order as spo ON wi.purchase_id = spo.id and spo.bool_delete_enum = 0 WHERE wid.bool_delete_enum = 0
AND wi.purchase_id = #{purchaseId}
AND wi.supplier_id = #{supplierId}
AND DATE(wid.inbound_time) >= date(#{startDate})
AND DATE(wid.inbound_time) <= date(#{endDate})
AND wi.basic_class = #{basicClass}
AND wid.classify_id = #{classifyId}
AND wid.classify_name like concat('%',#{classifyName},'%')
AND wi.purchase_SN like concat('%',#{purchaseSn},'%')
AND wi.id = #{inboundId}
AND wi.serial_number like concat('%',#{inboundSn},'%')
order by wid.inbound_time DESC, wid.id DESC

SELECT IFNULL(SUM(wi.amount), 0) FROM wms_inbound AS wi INNER JOIN scm_purchase_order AS spo ON wi.purchase_id = spo.id AND spo.bool_delete_enum = 0 WHERE wi.bool_delete_enum = 0 AND wi.review_status = 2
AND wi.supplier_id = #{supplierId}
and spo.id = #{purchaseId}

select wid.*, wc.name classifyName, wi.review_time wrt, wm.*, p.short_name psName, p.serial_number psNumber, pm.name pmName, pa.name paName, ww.name wwName, wi.serial_number wsn, spo.serial_number ssn, ss.name sn, wr.review_time wrTime from wms_inbound_detail wid left join wms_inbound wi on wid.inbound_id = wi.id left join wms_classification wc on wid.classify_id = wc.id left join wms_measure wm on wm.classification_id = wid.classify_id left join scm_supplier ss on ss.id = wi.supplier_id left join scm_purchase_order spo on spo.id = wi.purchase_id left join contract_project p on p.id = wid.project_id left join plan_monomer pm on pm.id = wid.monomer_id left join plan_area pa on pa.id = wid.area_id left join wms_warehouse ww on wid.warehouse_id = ww.id left join wms_reject_detail wrd on wrd.inbound_detail_id=wid.id left join wms_reject wr on wr.id=wrd.reject_id where wid.bool_delete_enum = 0 and wi.review_status = 2
and wid.basic_class & #{ basicClass} > 0
and wid.bool_party_a = 1
and wid.bool_party_a = 0
and wid.reject_status = #{rejectStatus}
and wi.supplier_id = #{supplierId}
and wid.workshop_id = #{workshopId}
and wid.warehouse_id = #{warehouseId}
and wi.purchase_SN like CONCAT('%', #{purchaseSN},'%')
and wi.serial_number like CONCAT('%', #{inboundSN},'%')
and wi.license_plate like CONCAT('%', #{licensePlate},'%')
and wi.shipment_number like CONCAT('%', #{shipmentNumber},'%')
and (wi.editor_name like CONCAT('%', #{operatorName},'%') or wi.applicant_name like CONCAT('%', #{operatorName},'%') or wi.reviewer_name like CONCAT('%', #{operatorName},'%'))
and wid.project_id is null
and wid.project_id IS NOT NULL
AND wid.project_id = #{projectId}
and wid.classify_id in
#{item}
and wi.review_time > #{inboundTime[0]}
and wi.review_time < #{inboundTime[1]}
and wid.specification like CONCAT('%', #{specification},'%')
and wid.heat_no_and_batch_no like CONCAT('%', #{heatNoAndBatchNo},'%')
and wi.purchase_SN like CONCAT('%', #{purchaseSN},'%')
AND wid.brand like CONCAT('%', #{brand},'%')
and wid.theory_thickness = #{theoryThickness}
and wid.thickness = #{thickness}
and wid.width = #{width}
and wid.length = #{length}
-- 长度范围只用于钢卷查询,钢卷quantity计量量记录长度
and wid.quantity >= #{minLength}
and wid.quantity <= #{maxLength}
and wid.color like CONCAT('%', #{color},'%')
and wid.workshop_id in
#{item}
and wi.inbound_way = #{inboundWay}
order by wid.id desc

select wi.review_time inboundTime, wi.review_time reviewTime, wi.create_time createTime, wi.user_update_time userUpdateTime, wi.id wid, wi.serial_number serialNumber, wi.shipment_number shipmentNumber, wi.license_plate licensePlate, wi.supplier_id supplierId, ss.name supplierName, spo.id purchaseId, spo.serial_number purchaseSN, wi.applicant_name applicantName, wi.editor_name editorName, wi.reviewer_name reviewerName, wid.*, ww.id warehouseId, ww.name warehouseName, p.id pid, p.short_name psName, p.serial_number pSN, p.name pn, mf.id workshopId, mf.name workshopName from wms_inbound_detail wid left join contract_project p on p.id = wid.project_id left join wms_inbound wi on wid.inbound_id = wi.id left join wms_warehouse ww on wid.warehouse_id = ww.id left join wms_workshop mf on mf.id = wid.workshop_id left join scm_supplier ss on ss.id = wi.supplier_id left join scm_purchase_order spo on spo.id = wi.purchase_id where wid.bool_delete_enum = 0 and wid.quality_testing_enum & #{qualityTestingEnum} > 0
and wid.basic_class & #{ basicClass} > 0
and wi.supplier_id = #{supplierId}
and wi.purchase_SN like CONCAT('%', #{purchaseSN},'%')
and wi.serial_number like CONCAT('%', #{serialNumber},'%')
and wi.license_plate like CONCAT('%', #{licensePlate},'%')
and wi.shipment_number like CONCAT('%', #{shipmentNumber},'%')
and (wi.quality_testing_user_name like CONCAT('%', #{operatorName},'%') or wi.applicant_name like CONCAT('%', #{operatorName},'%'))
and wi.create_time > #{createTime[0]}
and wi.create_time < #{createTime[1]}

select wid.*, wi.review_time wirt, p.id pid, p.short_name psName, p.serial_number pSN, p.name pn, pm.name pmName, pa.name paName from wms_inbound_detail wid left join wms_inbound wi on wid.inbound_id = wi.id left join contract_project p on p.id = wid.project_id left join plan_monomer pm on pm.id = wid.monomer_id left join plan_area pa on pa.id = wid.area_id where wid.bool_delete_enum = 0 and wi.review_status = 2
and DATE_FORMAT(wi.review_time,'%Y') = #{year}
and wi.supplier_id = #{supplierId}
and wi.purchase_id = #{purchaseId}
and wid.classify_id in
#{item}
and (wi.review_time > #{dateList[0]} and wi.review_time < #{dateList[1]} )

