select IFNULL(sum(wid.quantity),0) as quantity, IFNULL(sum(wid.mete),0) as mete from wms_inbound_detail wid left join wms_inbound wi on wid.inbound_id = wi.id where wid.bool_delete_enum = 0 and wid.basic_class != 256
and wi.review_status in
#{status}
and wi.purchase_id = #{purchaseId}

select
a.*
from wms_inbound_detail a
left join wms_inbound b on a.inbound_id = b.id
left join scm_purchase_order as c on a.purchase_id = c.id
where a.bool_delete_enum = 0
and a.bool_party_a = 0
and a.purchase_id is not null
and b.bool_delete_enum = 0
and b.review_status = 2
and a.reject_status <> 8

    and c.branch_company_id = #{branchCompanyId}


    AND DATE_FORMAT(a.inbound_time, "%Y")=DATE_FORMAT(#{yearDate}, "%Y")


    and (a.specification like CONCAT('%', #{material},'%') or a.do_not_section_steel_spec like CONCAT('%', #{material},'%'))


    and a.section_steel_spec like CONCAT('%', #{sectionSteelSpec},'%')


    and a.bool_cross = #{boolCross}


    AND a.monomer_id = #{monomerId}


    AND a.area_id = #{areaId}


    and a.workshop_id = #{workshopId}


    and a.warehouse_id = #{warehouseId}


    and a.project_id = #{projectId}


    and a.theory_thickness = #{theoryThickness}


    and a.thickness = #{thickness}


    and a.basic_class & #{ basicClass} > 0


    and a.width = #{width}


    and a.length = #{length}


    and a.quantity >= #{minLength}


    and a.quantity <= #{maxLength}


    and a.color like CONCAT('%', #{color},'%')


    and a.brand like CONCAT('%', #{brand},'%')


    and a.specification like CONCAT('%', #{specification},'%')


    and a.classify_id in
    
        #{item}
    


    and a.heat_no_and_batch_no in
    
        #{item}
    


    and a.heat_no_and_batch_no like CONCAT('%', #{heatNoAndBatchNo},'%')


    and a.classify_name like CONCAT('%', #{classifyName},'%')

        SELECT
        wid.*
        FROM
        wms_inbound_detail wid
        LEFT JOIN wms_inbound wi ON wid.inbound_id = wi.id and wi.bool_delete_enum = 0
        WHERE
        wid.bool_delete_enum = 0
        
            AND wi.purchase_id = #{purchaseId}
        
        
            AND wid.purchase_order_detail_id = #{purchaseDetailId}
        
        
            AND  wi.review_status = #{reviewStatus}

SELECT wid.id id, wid.purchase_order_detail_id purchaseDetailId, spo.id purchaseId, "1" type, wi.review_time createTime FROM wms_inbound_detail wid INNER JOIN wms_inbound wi ON wid.inbound_id = wi.id AND wi.bool_delete_enum = 0 AND wi.review_status = 2 INNER JOIN scm_purchase_order spo ON wi.purchase_id = spo.id AND spo.bool_delete_enum = 0 AND spo.data_status = 2 WHERE wid.bool_delete_enum = 0 AND spo.data_status = 2
and wid.basic_class & #{query.basicClassBit} > 0
and wid.basic_class = #{query.basicClass}
and wi.applicant_name like CONCAT('%', #{query.createUser},'%')
and wid.classify_name like CONCAT('%', #{query.className},'%')
and wi.review_time >= #{query.startTime}
and wi.review_time <= #{query.endTime}
and wid.project_id = #{query.projectId}
and spo.serial_number like CONCAT('%', #{query.purchaseSerialNumber},'%')
and spo.supplier_id = #{query.supplierId}
and wid.specification like CONCAT('%', #{query.specification},'%')
and spo.branch_company_id = #{query.branchCompanyId}

SELECT wid.amount amount, wid.amount_excluding_vat amountExcludingVat, wid.basic_class basicClass, wi.review_time inboundTime FROM wms_inbound_detail wid LEFT JOIN wms_inbound wi ON wid.inbound_id = wi.id and wi.bool_delete_enum = 0 AND wi.review_status = 2 WHERE wid.bool_delete_enum = 0
and wid.workshop_id = #{workshopId}
AND wi.review_time >= #{startDay}
AND wi.review_time <= #{endDay}
